insert into public.blogs (id,title,excerpt,author,author_avatar,category,tags,read_time,publish_date,source_name,url,cover_image,cover_alt,cover_fit,status,featured) values
('david-chapman-how-to-do-research-at-the-mit-ai-lab','How to do Research At the MIT AI Lab','A first-hand apprenticeship manual assembled by MIT AI Lab graduate students, covering how to read AI papers, keep notebooks, choose problems, work with advisors, write, give talks, and manage the emotional side of a PhD. The 1988 working paper reflects a pre-deep-learning AI culture, so its tools and community references are dated even where the habits still transfer.','David Chapman and MIT AI Lab graduate students','https://www.google.com/s2/favicons?domain=mit.edu&sz=128','How to Research',array['Graduate School','Research Habits','Reading Papers','Lab Culture'],'45 min read','1988-09-01','MIT DSpace','https://dspace.mit.edu/bitstream/handle/1721.1/41487/AI_WP_316.pdf','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('stephen-stearns-some-modest-advice-for-graduate-students','Some Modest Advice for Graduate Students','Stephen Stearns delivers deliberately blunt survival rules for graduate students: always prepare for the worst, know exactly why your work matters, write a thesis plan early, and take psychological control of your own project instead of waiting to be saved. Written for evolutionary biologists in 1987, its sharp tone and field norms predate modern CS and ML graduate culture.','Stephen C. Stearns','https://www.google.com/s2/favicons?domain=stearnslab.yale.edu&sz=128','How to Research',array['Graduate School','Career Advice','Thesis Planning','Academic Survival'],'12 min read','1987-01-01','Stearns Lab, Yale University','https://stearnslab.yale.edu/modest-advice','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('terence-tao-learn-and-relearn-your-field','Learn and Relearn Your Field','Terence Tao argues that even experts should keep re-deriving their own field: seek alternative proofs, check why each hypothesis in a result is necessary, test claims against model examples, and chase down why cited results are actually true. The advice is grounded in pure mathematics, so empirical ML readers must translate proof-centric habits into experiment-centric ones.','Terence Tao','https://www.google.com/s2/favicons?domain=terrytao.wordpress.com&sz=128','How to Research',array['Mathematical Research','Learning','Fundamentals','Career Advice'],'6 min read','2007-01-01','Terence Tao','https://terrytao.wordpress.com/career-advice/learn-and-relearn-your-field/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('terence-tao-on-the-importance-of-partial-progress','On the Importance of Partial Progress','Tao reframes failed attacks on a problem as reusable assets: partial results, toy cases, and the exact point where a method breaks down all help locate the true obstruction and often seed later solutions. His examples come from mathematical problem solving, where partial progress can be stated far more precisely than in empirical ML work.','Terence Tao','https://www.google.com/s2/favicons?domain=terrytao.wordpress.com&sz=128','How to Research',array['Problem Solving','Research Strategy','Mathematics','Persistence'],'6 min read','2012-07-17','Terence Tao','https://terrytao.wordpress.com/career-advice/on-the-importance-of-partial-progress/','assets/img/covers/cover-knowledge-representation.svg','Thematic research taste and problem-choice cover','cover','published',false),
('terence-tao-take-the-initiative','Take the Initiative','Tao urges students not to wait for advisors to hand them problems: read beyond assigned material, ask your own questions, explore variations of known results, and volunteer for tasks slightly beyond your comfort zone. The framing assumes mathematics academia, where self-directed problem generation is the main currency of a career.','Terence Tao','https://www.google.com/s2/favicons?domain=terrytao.wordpress.com&sz=128','How to Research',array['Initiative','Graduate School','Mathematics','Career Advice'],'5 min read','2007-01-01','Terence Tao','https://terrytao.wordpress.com/career-advice/take-the-initiative/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('ronald-azuma-so-long-and-thanks-for-the-phd','So Long, and Thanks for the Ph.D.! A Graduate School Survival Guide','Ronald Azuma''s long-running survival guide focuses on the traits that separate star graduate students from ordinary ones: initiative, tenacity, managing your advisor and committee, making daily progress, and planning the post-PhD job hunt early. Originally written in 1997 and last revised in 2019, it is rooted in US computer-science departments and pre-ML-boom career paths.','Ronald T. Azuma','https://www.google.com/s2/favicons?domain=cs.unc.edu&sz=128','How to Research',array['Graduate School','PhD Survival','Advising','Career Advice'],'40 min read','1997-01-01','UNC Computer Science','https://www.cs.unc.edu/~azuma/hitch4.html','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('jacob-steinhardt-film-study-for-research','Film Study for Research','Jacob Steinhardt borrows film study from athletics: researchers improve faster by replaying traces of expert work, such as reverse-engineering the decisions behind a paper, re-deriving results, and annotating talks, rather than only accumulating their own experience. The concrete drills are aimed at ML and statistics students with a steady stream of papers and seminars to study.','Jacob Steinhardt','https://www.google.com/s2/favicons?domain=jsteinhardt.stat.berkeley.edu&sz=128','How to Research',array['Deliberate Practice','Research Training','Skill Building','Machine Learning'],'12 min read','2021-06-28','Jacob Steinhardt','https://jsteinhardt.stat.berkeley.edu/blog/film-study','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('jacob-steinhardt-advice-for-authors','Advice for Authors','Distilled from reviewing batches of ICML submissions, Steinhardt''s advice concentrates on local writing style: be precise to maximize information content, prefer concrete claims over vague ones, and treat sentence-level clarity as more important than global structure. It is a compact reviewer''s checklist rather than a full guide to composing a research paper.','Jacob Steinhardt','https://www.google.com/s2/favicons?domain=jsteinhardt.stat.berkeley.edu&sz=128','How to Research',array['Paper Writing','Scientific Writing','Peer Review','Machine Learning'],'8 min read','2017-02-28','Jacob Steinhardt','https://jsteinhardt.stat.berkeley.edu/blog/advice-for-authors','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('matt-might-the-illustrated-guide-to-a-phd','The Illustrated Guide to a Ph.D.','Matt Might compresses the PhD into a sequence of circle diagrams: all human knowledge is a disc, coursework and reading push you to its edge, and years of focused work produce one tiny dent in the boundary that you must keep in perspective. It is a perspective-setting visual parable rather than operational advice, best paired with more concrete guides.','Matt Might','https://www.google.com/s2/favicons?domain=matt.might.net&sz=128','How to Research',array['PhD','Perspective','Visual Essay','Graduate School'],'3 min read','2010-01-01','Matt Might','https://matt.might.net/articles/phd-school-in-pictures/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('matt-might-phd-thesis-proposal-is-a-contract','A Ph.D. Thesis Proposal Is a Contract','Matt Might tells students to treat the thesis proposal as a contract: specify concrete, falsifiable deliverables the committee agrees to up front, so the defense becomes checking off promised items instead of renegotiating scope under pressure. The framing assumes US-style CS committees and works less well where proposals are informal or research direction shifts late.','Matt Might','https://www.google.com/s2/favicons?domain=matt.might.net&sz=128','How to Research',array['Thesis Proposal','PhD','Advising','Graduate School'],'6 min read','2010-01-01','Matt Might','https://matt.might.net/articles/advice-for-phd-thesis-proposals/','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('chris-olah-research-taste-exercises','Research Taste Exercises','Chris Olah proposes concrete exercises for developing research taste: predict experiment outcomes before running them, generate long lists of project ideas and rank them, and dissect why landmark papers mattered. He explicitly labels the piece a rough note, so it is a starting kit of drills rather than a polished, carefully defended framework.','Christopher Olah','https://www.google.com/s2/favicons?domain=colah.github.io&sz=128','How to Research',array['Research Taste','Deliberate Practice','Machine Learning','Idea Generation'],'10 min read','2021-01-09','colah''s blog','https://colah.github.io/notes/taste/','assets/img/covers/cover-knowledge-representation.svg','Thematic research taste and problem-choice cover','cover','published',false),
('nick-feamster-cultivating-your-research-taste','Cultivating Your Research Taste','Nick Feamster treats taste in research problems like taste in music or design: it is cultivated deliberately through broad reading, apprenticeship with people whose judgment you trust, and reflection on why certain problems reward years of investment. The essay generalizes from his systems and networking career, so the calibration differs for fast-moving ML subfields.','Nick Feamster','https://www.google.com/s2/favicons?domain=practicespace.substack.com&sz=128','How to Research',array['Research Taste','Choosing Problems','Mentorship','Research Careers'],'9 min read','2025-10-29','Practice Space','https://practicespace.substack.com/p/cultivating-your-research-taste-fbd','https://substackcdn.com/image/fetch/$s_!Je_o!,w_1200,h_675,c_fill,f_jpg,q_auto:good,fl_progressive:steep,g_auto/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F3eb308a1-4c4f-4743-b18e-97f798974cc9_800x438.png','Real cover from og:image','cover','published',false),
('john-regehr-picking-a-research-topic','Picking a Research Topic in Computer Systems','John Regehr offers pragmatic heuristics for picking a topic: separate choosing a research area from choosing a problem, be honest about the crowd you would be competing with, and favor problems where you hold an unfair advantage in tools or perspective. The examples are systems-flavored and predate today''s ML-dominated publication economy.','John Regehr','https://www.google.com/s2/favicons?domain=blog.regehr.org&sz=128','How to Research',array['Choosing Problems','Computer Systems','Graduate School','Research Strategy'],'8 min read','2010-03-21','Embedded in Academia','https://blog.regehr.org/archives/46','assets/img/covers/cover-knowledge-representation.svg','Thematic research taste and problem-choice cover','cover','published',false),
('jason-eisner-how-to-find-research-problems','How to Find Research Problems','Jason Eisner maps the ecosystem of research contributions from small bones to big ones: reimplementations, generalizations, connections between fields, and new formalisms, showing how new PhD students can deliberately climb that ladder. Written in 1997 for Penn CS students, its examples predate the statistical and neural NLP field Eisner later helped build.','Jason Eisner','https://www.google.com/s2/favicons?domain=cs.jhu.edu&sz=128','How to Research',array['Finding Problems','Research Contributions','NLP','Graduate School'],'10 min read','1997-01-01','Jason Eisner','https://www.cs.jhu.edu/~jason/advice/how-to-find-research-problems.html','assets/img/covers/cover-knowledge-representation.svg','Thematic research taste and problem-choice cover','cover','published',false),
('noah-smith-grad-school-advice','Grad School Advice','Noah Smith memoizes the advice he repeatedly gives PhD applicants: pick people over institutional prestige, evaluate potential advisors by how their students actually spend their days, and treat visit days as data-gathering interviews rather than sales pitches. It targets US computer-science admissions, where advisor choice dominates the doctoral experience.','Noah A. Smith','https://www.google.com/s2/favicons?domain=cs.cmu.edu&sz=128','How to Research',array['Graduate School','Choosing an Advisor','PhD Applications','Career Advice'],'6 min read','2007-01-01','Noah A. Smith','https://www.cs.cmu.edu/~nasmith/advice.html','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('simon-peyton-jones-how-to-write-a-great-research-proposal','How to Write a Great Research Proposal','Simon Peyton Jones structures a fundable proposal around three questions reviewers must be able to answer quickly: what is the problem, why is it interesting and timely, and why are you the team that can crack it, backed by evidence rather than promises. The slides come from UK research-council funding rounds, so mechanics differ from NSF-style or industrial proposals.','Simon Peyton Jones','https://www.google.com/s2/favicons?domain=simon.peytonjones.org&sz=128','How to Research',array['Research Proposals','Grant Writing','Research Communication','Talks'],'10 min read','2004-01-01','Simon Peyton Jones','https://simon.peytonjones.org/assets/pdfs/great-research-proposal.pdf','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('simon-peyton-jones-how-to-give-a-great-research-talk','How to Give a Great Research Talk','With John Hughes and John Launchbury, Peyton Jones frames the talk as an advertisement for the paper: lead with a motivating example instead of an outline, present one key idea with enough depth to be believed, and cut every slide that serves the speaker rather than the audience. The deck has been refined since 1993 in the programming-languages community, so pacing norms reflect academic CS venues.','Simon Peyton Jones','https://www.google.com/s2/favicons?domain=simon.peytonjones.org&sz=128','How to Research',array['Research Talks','Presentations','Research Communication','Slides'],'10 min read','1993-01-01','Simon Peyton Jones','https://simon.peytonjones.org/assets/pdfs/giving-a-talk.pdf','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('cs-guides-computer-science-graduate-job-guide','Computer Science Graduate Job and Interview Guide','A community-written guide to the post-PhD job search in computer science: finding openings, assembling research and teaching statements, surviving interviews and job talks, and weighing offers, with real example materials donated by recent graduates. It covers the job market rather than day-to-day research skills, and its logistics are calibrated to North American academia and industry labs.','CS Guides Contributors','https://www.google.com/s2/favicons?domain=csguides.github.io&sz=128','How to Research',array['Job Market','Research Careers','Application Materials','Graduate School'],'25 min read','2020-01-01','CS Guides','https://csguides.github.io/grad-job-guide/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('visionbook-how-to-do-research','How to Do Research','Written as advice from advisor to student, this chapter of Foundations of Computer Vision covers the jump from problem sets to open problems: how to pick projects, budget attention, respond to setbacks, and build a daily research practice in little bites. The advice is shaped by computer-vision research at MIT, so some heuristics assume vision-style empirical projects.','Antonio Torralba, Phillip Isola, William T. Freeman','https://www.google.com/s2/favicons?domain=visionbook.mit.edu&sz=128','How to Research',array['Research Practice','Computer Vision','Graduate School','Advising'],'15 min read','2024-01-01','Foundations of Computer Vision','https://visionbook.mit.edu/how_to_do_research.html','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('visionbook-how-to-write-papers','How to Write Papers','Torralba, Isola, and Freeman argue that only the good papers count: they walk through organizing a paper around one clear contribution, designing figures that carry the argument, and revising until reviewers cannot misread the claim. Examples and conventions come from computer-vision venues, so section norms and figure-first style may differ in other communities.','Antonio Torralba, Phillip Isola, William T. Freeman','https://www.google.com/s2/favicons?domain=visionbook.mit.edu&sz=128','How to Research',array['Paper Writing','Computer Vision','Research Communication','Figures'],'12 min read','2024-01-01','Foundations of Computer Vision','https://visionbook.mit.edu/how_to_write_papers.html','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('visionbook-how-to-give-talks','How to Give Talks','The authors compare a good talk to a big serve in tennis: it does not win the game alone, but every top player has one. The chapter taxonomizes talk types, then gives concrete heuristics for structure, slide design, and delivery. It draws on decades of MIT vision-community presentations, so its style norms lean toward academic conference talks.','Antonio Torralba, Phillip Isola, William T. Freeman','https://www.google.com/s2/favicons?domain=visionbook.mit.edu&sz=128','How to Research',array['Research Talks','Presentations','Computer Vision','Communication'],'10 min read','2024-01-01','Foundations of Computer Vision','https://visionbook.mit.edu/how_to_give_talks.html','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('stanford-cs-phd-advising-guide','PhD Advising Guide','Stanford CS explains what advising is actually for: personalized teaching of how to choose projects, execute them, present results, and behave professionally, and lays out the rotation system plus the mutual expectations advisors and students should negotiate explicitly. The mechanics, quarterly rotations and alignment, are Stanford-specific even though the expectations framework transfers.','Stanford Computer Science Department','https://www.google.com/s2/favicons?domain=cs.stanford.edu&sz=128','How to Research',array['Advising','PhD Program','Lab Culture','Graduate School'],'20 min read','2023-01-01','Stanford Computer Science','https://www.cs.stanford.edu/phd-milestones-progress-guidelines/phd-advising-guide','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('umd-choosing-a-research-advisor','Choosing a Research Advisor','Udaya Shankar reduces advisor choice to two axes that students routinely under-weigh: the professor''s research area and, equally important, their style, meaning team size, depth versus breadth, and hands-on versus hands-off management. He recommends reading recent papers, interviewing current students, and taking a class before committing. It is a short departmental note, not a comprehensive guide.','A. Udaya Shankar','https://www.google.com/s2/favicons?domain=cs.umd.edu&sz=128','How to Research',array['Choosing an Advisor','Graduate School','Advising','Research Careers'],'4 min read','2010-01-01','UMD Computer Science','https://www.cs.umd.edu/grad/choosing-your-advisor','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('mor-harchol-balter-applying-to-phd-programs-in-computer-science','Applying to Ph.D. Programs in Computer Science','Mor Harchol-Balter demystifies CS PhD admissions from the committee''s side: research experience and strong letters dominate grades and test scores, the statement of purpose must show evidence of research ability, and school choice should follow advisor fit rather than rankings. Figures and process details reflect US admissions around 2014.','Mor Harchol-Balter','https://www.google.com/s2/favicons?domain=cs.cmu.edu&sz=128','How to Research',array['PhD Applications','Graduate School','Admissions','Career Advice'],'20 min read','2014-01-01','Carnegie Mellon University','https://www.cs.cmu.edu/~harchol/gradschooltalk.pdf','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('jason-wei-practicing-ai-research','Practicing AI Research','Jason Wei treats research as a learnable skill like sports or music and decomposes it into four trainable sub-skills: idea conception and selection, experiment design and execution, paper writing, and maximizing impact after publication. The playbook reflects big-lab LLM research, where fast experiment cycles and public visibility matter more than in slower fields.','Jason Wei','https://www.google.com/s2/favicons?domain=jasonwei.net&sz=128','How to Research',array['AI Research','Deliberate Practice','Research Skills','Career Advice'],'9 min read','2023-02-07','Jason Wei','https://www.jasonwei.net/blog/practicing-ai-research','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('neel-guha-templates-for-machine-learning-research-papers','Templates for Machine Learning Research Papers','Neel Guha argues that ML papers follow a small set of recurring templates, and that authors get rejected when they mix templates or skip an argument their chosen template obligates them to make; identifying your template tells you exactly which experiments and framings reviewers will demand. The taxonomy is specific to current ML publication culture and reviewing norms.','Neel Guha','https://www.google.com/s2/favicons?domain=neelguha.github.io&sz=128','How to Research',array['Paper Writing','Machine Learning','Publication Strategy','Research Communication'],'14 min read','2026-03-24','Neel Guha','https://neelguha.github.io/blog/2026/templates/','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('google-brain-team-approach-to-research','The Google Brain Team''s Approach to Research','Jeff Dean describes how Google Brain balances curiosity-driven and application-driven work: researchers set their own agendas, results ship through open publication and open-source tools, and product deployments feed new research questions back into the lab. It is a 2017 snapshot of one industrial lab''s culture, written before the LLM era reorganized industry research.','Jeff Dean','https://www.google.com/s2/favicons?domain=research.google&sz=128','How to Research',array['Lab Culture','Industrial Research','Google Brain','Research Strategy'],'8 min read','2017-09-13','Google Research Blog','https://research.google/blog/the-google-brain-teams-approach-to-research/','https://storage.googleapis.com/gweb-research2023-media/images/53f67c7f3ba7c094ad0b59ab3f986902-g.width-800.format-jpeg.jpg','Real cover from og:image','cover','published',false),
('microsoft-research-first-accomplishment-in-the-nlp-field','How to Make a First Accomplishment in the NLP Field','Microsoft Research Asia''s NLP group advises newcomers on landing a first real contribution: master the fundamentals, reproduce classic systems before trying to innovate, scope a tractable first problem, and iterate with senior collaborators. The framing reflects 2017 NLP, when reproducing pipelines was the standard apprenticeship, before pretrained LLMs changed entry paths.','Microsoft Research Asia','https://www.google.com/s2/favicons?domain=microsoft.com&sz=128','How to Research',array['NLP','First Projects','Research Training','Mentorship'],'10 min read','2017-12-05','Microsoft Research','https://www.microsoft.com/en-us/research/articles/make-first-accomplishment-nlp-field/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('distill-research-debt','Research Debt','Olah and Carter name the friction that accumulates when ideas pile up faster than they are digested: research debt. They argue that distillation, meaning clear explanations, notation cleanup, and interactive exposition, is real research labor that deserves career credit. It is a manifesto about communicating research, and the distiller career track it calls for has only partially materialized since 2017.','Chris Olah and Shan Carter','https://www.google.com/s2/favicons?domain=distill.pub&sz=128','How to Research',array['Research Debt','Distillation','Research Communication','Explanation'],'10 min read','2017-03-22','Distill','https://distill.pub/2017/research-debt/','https://distill.pub/2017/research-debt/thumbnail.jpg','Real cover from og:image','cover','published',false),
('distill-communicating-with-interactive-articles','Communicating with Interactive Articles','Hohman and coauthors survey what interactive articles can do that PDFs cannot: reader-driven exploration, multiple linked representations, and play as a path to intuition, drawing on examples across journalism and research. Building such artifacts remains far more expensive than writing static papers, which the piece acknowledges as the central barrier to adoption.','Fred Hohman, Matthew Conlen, Jeffrey Heer, Duen Horng Chau','https://www.google.com/s2/favicons?domain=distill.pub&sz=128','How to Research',array['Interactive Articles','Research Communication','Visualization','Explorable Explanations'],'18 min read','2020-09-11','Distill','https://distill.pub/2020/communicating-with-interactive-articles/','https://distill.pub/2020/communicating-with-interactive-articles/thumbnail.jpg','Real cover from og:image','cover','published',false),
('andrej-karpathy-a-survival-guide-to-a-phd','A Survival Guide to a PhD','Karpathy walks through the full PhD arc: deciding whether to enroll at all, picking an advisor and problem by maximizing interestingness times feasibility, structuring papers as the unit of progress, giving talks, and protecting your psychology through dry spells. Written in 2016 from a CS and vision vantage point, before industrial labs became the default destination for ML researchers.','Andrej Karpathy','https://www.google.com/s2/favicons?domain=karpathy.github.io&sz=128','How to Research',array['PhD Survival','Machine Learning','Choosing Problems','Career Advice'],'25 min read','2016-09-07','Andrej Karpathy','https://karpathy.github.io/2016/09/07/phd/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('john-schulman-an-opinionated-guide-to-ml-research','An Opinionated Guide to ML Research','John Schulman divides ML research into choosing problems and making progress on them: he contrasts goal-driven with idea-driven research, recommends developing taste through reimplementation and textbook study, and prescribes incremental daily progress recorded in a notebook. The essay is served over plain HTTP only, and its examples skew toward the deep RL agenda of his OpenAI years.','John Schulman','https://www.google.com/s2/favicons?domain=joschu.net&sz=128','How to Research',array['ML Research','Choosing Problems','Research Taste','Deep RL'],'15 min read','2020-01-01','John Schulman','http://joschu.net/blog/opinionated-guide-ml-research.html','assets/img/covers/cover-knowledge-representation.svg','Thematic research taste and problem-choice cover','cover','published',false),
('markus-heinonen-advice-for-ml-phd-students','Advice for Machine Learning PhD Students','Markus Heinonen compresses an ML PhD into three pillars in priority order: understanding, communicating, and implementing, arguing that clarity is all you need: rework the math until an outsider grasps it at a glance, and minimize coding time by maximizing understanding. The advice reflects European PhD structures at Aalto, with less coursework than US programs.','Markus Heinonen','https://www.google.com/s2/favicons?domain=markusheinonen.github.io&sz=128','How to Research',array['Machine Learning','PhD Advice','Clarity','Research Skills'],'10 min read','2025-01-01','Markus Heinonen','https://markusheinonen.github.io/advice.html','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('michael-fischbach-how-to-pick-and-solve-the-next-great-problem','How to Pick and Solve the Next Great Problem','This Stanford Engineering piece distills Michael Fischbach''s course on problem choice: work through an explicit decision tree that asks whether a problem is important, tractable now, and matched to your unfair advantages before committing years to it. It is a news-article summary of the course rather than the full framework, and its worked examples come from bioengineering.','Stanford Engineering / Michael Fischbach','https://www.google.com/s2/favicons?domain=stanford.edu&sz=128','How to Research',array['Choosing Problems','Decision Frameworks','Research Strategy','Stanford'],'7 min read','2024-10-23','Stanford Engineering','https://engineering.stanford.edu/news/how-pick-and-solve-next-great-problem','https://engineering.stanford.edu/sites/default/files/styles/card_1192x596/public/media/image/edit_fischbach_0.jpg?h=0a4727b2&itok=FJaUAPoj','Real cover from og:image','cover','published',false),
('eugene-yan-choosing-problems-in-data-science-and-machine-learning','Choosing Problems in Data Science and Machine Learning','Eugene Yan turns problem selection into an explicit rubric: score candidate problems on impact via reach and severity, cost-benefit, fit with your capabilities, and learning value, then maintain a portfolio balanced across time horizons. The lens is industry data science, where problems are chosen against business value rather than academic novelty.','Eugene Yan','https://www.google.com/s2/favicons?domain=eugeneyan.com&sz=128','How to Research',array['Choosing Problems','Data Science','Prioritization','Machine Learning'],'9 min read','2021-03-21','Eugene Yan','https://eugeneyan.com/writing/how-to-choose-problems/','https://eugeneyan.com/assets/og_image/choosing-problems.jpg','Real cover from og:image','cover','published',false),
('richard-hamming-you-and-your-research','You and Your Research','Hamming''s Bell Labs talk asks why so few scientists do important work and answers with habits: work on problems that matter, keep your door open, turn hard conditions into advantage, and sell your results, because courage and effort compound like interest. The anecdotes are mid-century physics and engineering, and some framing, like his remarks on drive and family, is dated.','Richard Hamming','https://www.google.com/s2/favicons?domain=cs.virginia.edu&sz=128','How to Research',array['Important Problems','Research Careers','Bell Labs','Classic Talks'],'30 min read','1986-03-07','University of Virginia (transcript)','https://www.cs.virginia.edu/~robins/YouAndYourResearch.html','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('michael-nielsen-principles-of-effective-research','Principles of Effective Research','Nielsen splits effective research into self-development and creative work, and insists both rest on proactive personal responsibility: pick problems at the intersection of importance and your comparative advantage, and manage your own growth rather than outsourcing it to institutions. He wrote it as a letter to himself in 2004, so parts are specific to a theoretical physicist''s career.','Michael Nielsen','https://www.google.com/s2/favicons?domain=michaelnielsen.org&sz=128','How to Research',array['Effective Research','Self-Development','Choosing Problems','Research Careers'],'20 min read','2004-07-27','Michael Nielsen','https://michaelnielsen.org/blog/principles-of-effective-research/','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false),
('david-patterson-how-to-have-a-bad-career','How to Have a Bad Career in Research/Academia','Patterson teaches by inversion: to have a bad career, worship complexity, avoid feedback, and maximize paper count; he then flips each vice into advice for impact, such as picking five-year goals, building real systems, and running healthy project teams. It is a talk deck honed over years in the systems community, so the jokes and case studies are 1990s Berkeley.','David A. Patterson','https://www.google.com/s2/favicons?domain=berkeley.edu&sz=128','How to Research',array['Research Careers','Impact','Systems Research','Classic Talks'],'15 min read','1997-01-01','UC Berkeley EECS','https://people.eecs.berkeley.edu/~pattrsn/talks/BadCareer.pdf','assets/img/covers/cover-research-adjudication.svg','Thematic research writing and review cover','cover','published',false),
('keshav-how-to-read-a-paper','How to Read a Paper','Keshav''s two-page classic prescribes the three-pass method: a five-minute bird''s-eye pass, an hour-long content pass, and a deep pass where you virtually re-implement the paper, plus a recipe for literature surveys built on the same passes. The method itself has aged well, though the paper''s pointers to further reading are now out of date.','S. Keshav','https://www.google.com/s2/favicons?domain=cl.cam.ac.uk&sz=128','How to Research',array['Reading Papers','Three-Pass Method','Literature Surveys','Graduate School'],'6 min read','2007-07-01','University of Cambridge','https://svr-sk818-web.cl.cam.ac.uk/keshav/papers/07/paper-reading.pdf','assets/img/covers/cover-lilian-research.svg','Thematic research practice cover','cover','published',false)
